-- ==========================================================-- Atlas-- Migration: 0001_create_organizations-- Description: Create organizations table-- Version: 1.0-- ==========================================================BEGIN;-- ==========================================================-- ENUMS-- ==========================================================CREATE TYPE subscription_plan AS ENUM ('FREE','STARTER','PROFESSIONAL','BUSINESS','ENTERPRISE');CREATE TYPE subscription_status AS ENUM ('TRIAL','ACTIVE','SUSPENDED','CANCELLED','EXPIRED');-- ==========================================================-- TABLE-- ==========================================================CREATE TABLE organizations (    -- Primary Key    id UUID PRIMARY KEY,    -- Identity    legal_name VARCHAR(255) NOT NULL,    display_name VARCHAR(255) NOT NULL,    slug VARCHAR(100) NOT NULL UNIQUE,    registration_number VARCHAR(100),    tax_number VARCHAR(100),    -- Contact    email VARCHAR(255) NOT NULL,    phone VARCHAR(50),    website TEXT,    -- Branding    logo_url TEXT,    primary_color VARCHAR(20),    secondary_color VARCHAR(20),    -- Address    address_line_1 TEXT,    address_line_2 TEXT,    city VARCHAR(100),    state_province VARCHAR(100),    postal_code VARCHAR(30),    country VARCHAR(100) NOT NULL,    -- Regional    timezone VARCHAR(100) NOT NULL DEFAULT 'UTC',    locale VARCHAR(20) NOT NULL DEFAULT 'en-ZA',    currency VARCHAR(10) NOT NULL DEFAULT 'ZAR',    -- Subscription    subscription_plan subscription_plan NOT NULL,    subscription_status subscription_status NOT NULL,    trial_ends_at TIMESTAMPTZ,    subscription_renews_at TIMESTAMPTZ,    -- Features    ai_enabled BOOLEAN NOT NULL DEFAULT TRUE,    voice_enabled BOOLEAN NOT NULL DEFAULT TRUE,    mobile_enabled BOOLEAN NOT NULL DEFAULT TRUE,    api_enabled BOOLEAN NOT NULL DEFAULT TRUE,    -- Security    require_mfa BOOLEAN NOT NULL DEFAULT FALSE,    session_timeout_minutes INTEGER        NOT NULL        DEFAULT 60,    password_policy JSONB,    -- Retention    document_retention_days INTEGER DEFAULT 2555,    audit_retention_days INTEGER DEFAULT 2555,    voice_retention_days INTEGER DEFAULT 365,    -- Audit    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),    created_by UUID,    updated_by UUID,    archived_at TIMESTAMPTZ,    -- Constraints    CONSTRAINT chk_session_timeout        CHECK (session_timeout_minutes > 0),    CONSTRAINT chk_document_retention        CHECK (document_retention_days >= 0),    CONSTRAINT chk_audit_retention        CHECK (audit_retention_days >= 0),    CONSTRAINT chk_voice_retention        CHECK (voice_retention_days >= 0));-- ==========================================================-- INDEXES-- ==========================================================CREATE INDEX idx_org_emailON organizations(email);CREATE INDEX idx_org_countryON organizations(country);CREATE INDEX idx_org_created_atON organizations(created_at);CREATE INDEX idx_org_subscription_statusON organizations(subscription_status);CREATE INDEX idx_org_archived_atON organizations(archived_at);COMMIT;